INSERT INTO questionnaire_record (
    patient_id, admission_number, assessment_date,
    selections, item_scores, total_score, category_scores,
    doctor_id, doctor_username, modified_by, user_input_data, create_time, update_time
) VALUES (
    #{patientId}, #{admissionNumber}, #{assessmentDate},
    #{selections}, #{itemScores}, #{totalScore}, #{categoryScores},
    #{doctorId}, #{doctorUsername}, #{modifiedBy}, #{userInputData}, #{createTime}, #{updateTime}
)

mapper.select:
SELECT qr.*, 
       p.name as patient_name, p.gender as patient_gender, p.phone as patient_phone,
       d.username as doctor_name, d.employee_number as doctor_employee_number
FROM questionnaire_record qr
LEFT JOIN patient p ON qr.patient_id = p.id
LEFT JOIN doctor d ON qr.doctor_id = d.id
WHERE qr.patient_id = #{patientId}

    AND qr.assessment_date >= #{startDate}


    AND qr.assessment_date <= #{endDate}

ORDER BY qr.assessment_date DESC, qr.create_time DESC

SELECT qr.*, p.name as patient_name, p.gender as patient_gender, p.phone as patient_phone, d.username as doctor_name, d.employee_number as doctor_employee_number FROM questionnaire_record qr LEFT JOIN patient p ON qr.patient_id = p.id LEFT JOIN doctor d ON qr.doctor_id = d.id INNER JOIN patient_doctor pd ON qr.patient_id = pd.patient_id WHERE qr.patient_id = #{patientId} AND pd.doctor_id = #{doctorId}
AND qr.assessment_date >= #{startDate}
AND qr.assessment_date <= #{endDate}
ORDER BY qr.assessment_date DESC, qr.create_time DESC

SELECT qr.*, 
       p.name as patient_name, p.gender as patient_gender, p.phone as patient_phone,
       d.username as doctor_name, d.employee_number as doctor_employee_number
FROM questionnaire_record qr
LEFT JOIN patient p ON qr.patient_id = p.id
LEFT JOIN doctor d ON qr.doctor_id = d.id
WHERE qr.admission_number = #{admissionNumber}

    AND qr.assessment_date >= #{startDate}


    AND qr.assessment_date <= #{endDate}

ORDER BY qr.assessment_date DESC, qr.create_time DESC

SELECT qr.*, p.name as patient_name, p.gender as patient_gender, p.phone as patient_phone, d.username as doctor_name, d.employee_number as doctor_employee_number FROM questionnaire_record qr LEFT JOIN patient p ON qr.patient_id = p.id LEFT JOIN doctor d ON qr.doctor_id = d.id
AND (p.name LIKE CONCAT('%', #{patientName}, '%') OR qr.admission_number LIKE CONCAT('%', #{patientName}, '%'))
AND qr.assessment_date >= #{startDate}
AND qr.assessment_date <= #{endDate}
ORDER BY qr.create_time DESC
LIMIT #{offset}, #{pageSize}

SELECT COUNT(*) FROM questionnaire_record qr
INNER JOIN patient p ON qr.patient_id = p.id
AND (p.name LIKE CONCAT('%', #{patientName}, '%') OR qr.admission_number LIKE CONCAT('%', #{patientName}, '%'))
AND qr.assessment_date >= #{startDate}
AND qr.assessment_date <= #{endDate}

SELECT qr.*, p.name as patient_name, p.gender as patient_gender, p.phone as patient_phone, d.username as doctor_name, d.employee_number as doctor_employee_number FROM questionnaire_record qr LEFT JOIN patient p ON qr.patient_id = p.id LEFT JOIN doctor d ON qr.doctor_id = d.id INNER JOIN patient_doctor pd ON qr.patient_id = pd.patient_id
AND pd.doctor_id = #{doctorId}
AND (p.name LIKE CONCAT('%', #{patientName}, '%') OR qr.admission_number LIKE CONCAT('%', #{patientName}, '%'))
AND qr.assessment_date >= #{startDate}
AND qr.assessment_date <= #{endDate}
ORDER BY qr.create_time DESC
LIMIT #{offset}, #{pageSize}

SELECT COUNT(*)
FROM questionnaire_record qr
INNER JOIN patient_doctor pd ON qr.patient_id = pd.patient_id

    INNER JOIN patient p ON qr.patient_id = p.id


    AND pd.doctor_id = #{doctorId}

        AND (p.name LIKE CONCAT('%', #{patientName}, '%')
